/* P00.3: visual simplification of A; catalog and detail primitives remain shared. */
window.Concepts = window.Concepts || {};
window.Concepts.A = {
  home(H,s){return `${H.header('editorial')}<main id="main" class="a-main" tabindex="-1">
    <section class="a-feature" aria-labelledby="a-home-title"><div class="a-container a-feature-inner"><div class="a-feature-copy"><div class="a-feature-brand">${H.icon(H.get('localsend'),'md')}<span>LocalSend</span></div><h1 id="a-home-title">Chuyển tệp.<br><span>Nhẹ như không.</span></h1><a class="a-feature-link" href="${H.url('detail/localsend')}">Khám phá LocalSend ${H.symbol('arrow')}</a><div class="a-hero-search">${H.search('','a-home-search','Tìm tài nguyên…')}</div></div><a class="a-feature-media" href="${H.url('detail/localsend')}" aria-label="Tìm hiểu LocalSend"><img class="a-device-desktop" src="assets/localsend-desktop.webp" alt="LocalSend chuyển tệp trên máy tính, ảnh sản phẩm từ nguồn chính thức" width="2000" height="1182" decoding="async"><img class="a-device-phone" src="assets/localsend-mobile.webp" alt="LocalSend trên điện thoại, ảnh sản phẩm từ nguồn chính thức" width="395" height="800" decoding="async"></a></div></section>
    <div class="a-container"><section class="a-curated" aria-labelledby="a-curated-title"><div class="section-heading"><h2 id="a-curated-title">Thêm cảm hứng.</h2><a class="text-link" href="${H.url('discover')}">Khám phá thêm ${H.symbol('arrow')}</a></div><div class="a-curated-grid">${H.pick(['excalidraw','godot']).map(r=>`<article class="a-spotlight-card"><a class="a-spotlight-link" href="${H.url('detail/'+r.id)}"><div class="a-spotlight-visual a-spotlight-${r.id}"><img src="${r.artwork||r.screenshot}" alt="${r.id==='excalidraw'?'Artwork giới thiệu Excalidraw từ nguồn chính thức, không phải screenshot':H.escape(r.screenshotAlt)}" width="${r.id==='excalidraw'?1200:1920}" height="${r.id==='excalidraw'?675:1080}" decoding="async">${r.id==='excalidraw'?'<span class="a-artwork-label">Artwork sản phẩm</span>':''}</div><div class="a-spotlight-info">${H.icon(r)}<div><h3>${H.escape(r.name)}</h3><p>${r.id==='excalidraw'?'Vẽ ý tưởng thành hình.':'Tạo thế giới của riêng bạn.'}</p></div><span class="a-spotlight-arrow" aria-hidden="true">${H.symbol('arrow')}</span></div></a></article>`).join('')}</div></section>
    <section class="a-invitation"><h2>Bạn biết một công cụ hay?</h2><button type="button" class="button secondary" data-open="contribute">Đóng góp tài nguyên ${H.symbol('plus')}</button></section>
  </div></main>${H.footer()}`;},
  discover(H,s){
    const list=s.params.get('view')==='list',params=Object.fromEntries(s.params),limit=Math.min(H.data.length,Math.max(8,Number(s.params.get('limit'))||8)),visible=s.filtered.slice(0,limit);
    return `${H.header('editorial')}<main id="main" class="a-main" tabindex="-1"><div class="a-container a-explore"><section class="a-explore-intro"><div><p class="a-kicker">KHÁM PHÁ THƯ VIỆN</p><h1>${s.query?'Tìm đúng điều bạn cần.':'Có một công cụ cho việc đó.'}</h1><p>Thu gọn theo nhu cầu. Đọc kỹ trước khi chọn.</p></div>${H.search(s.query,'a-discover-search','Tìm tên, công dụng hoặc chủ đề…')}</section><div class="a-explore-layout"><aside class="a-filter-rail"><details class="a-filters" open><summary>${H.symbol('filter')}Bộ lọc ${H.symbol('chevron')}</summary>${H.filters(s)}</details></aside><section class="a-results" aria-label="Kết quả tài nguyên"><div class="a-result-toolbar">${H.resultsHead(s)}<nav class="a-view-toggle" aria-label="Cách xem kết quả"><a href="${H.url('discover',{...params,view:'grid'})}" class="icon-button ${!list?'active':''}" aria-label="Xem dạng lưới" ${!list?'aria-current="true"':''}>${H.symbol('grid')}</a><a href="${H.url('discover',{...params,view:'list'})}" class="icon-button ${list?'active':''}" aria-label="Xem dạng danh sách" ${list?'aria-current="true"':''}>${H.symbol('list')}</a></nav></div>${visible.length?`<div class="${list?'a-catalog-list':'a-catalog-grid'}" id="a-catalog-results">${visible.map(r=>H.card(r,{minimal:true})).join('')}</div><div class="a-load-more"><p role="status" data-result-summary tabindex="-1">Đang xem ${visible.length} / ${s.filtered.length} tài nguyên mẫu</p>${visible.length<s.filtered.length?`<button type="button" class="button secondary" data-more="${limit+8}">Xem thêm ${H.symbol('plus')}</button>`:'<span>Bạn đã xem hết các lựa chọn phù hợp.</span>'}</div>`:H.empty(s)}</section></div></div></main>${H.footer()}`;
  },
  detail(H,r,s){return `${H.header('editorial')}<main id="main" class="a-main" tabindex="-1"><div class="a-container"><nav class="a-breadcrumb" aria-label="Đường dẫn"><a href="${H.url('discover')}">Thư viện</a><span>/</span><a href="${H.url('discover',{category:r.category})}">${H.escape(r.category)}</a><span>/</span><span>${H.escape(r.name)}</span></nav><section class="a-detail-intro"><div class="a-detail-identity">${H.icon(r,'lg')}<div><p class="a-kicker">${H.escape(r.category)}</p><h1>${H.escape(r.name)}</h1><p>${H.escape(r.summary)}</p></div></div><div class="a-detail-actions"><a class="button" href="${H.escape(r.homepage)}" target="_blank" rel="noopener noreferrer">Đến nguồn chính thức ${H.symbol('external')}</a><button type="button" class="button secondary" data-save="${r.id}">${H.symbol('bookmark')}Lưu trong phiên</button></div></section><div class="a-detail-visual">${H.preview(r)}</div><div class="a-detail-reading"><article>${H.article(r)}</article><aside><p class="a-kicker">TRƯỚC KHI BẠN THỬ</p>${H.facts(r)}</aside></div>${H.related(r)}</div></main>${H.footer()}`;}
};
